 return original==='AGENTS.md'?['.harness/config.json','.harness/features.json','.harness/continuity.json','.harness/run.mjs resume'].every(value=>content.includes(value)):(content.includes(original==='CLAUDE.md'?'@AGENTS.md':'AGENTS.md')||(content.includes('.harness/config.json')&&content.includes('.harness/features.json')));
