export async function sealAll11(){await audit();const {progress}=await loadBaseline();assert.equal(progress.pending,null);await checkContinuationArchive(progress);assert(progress.targets.every(r=>r.status==='audited'));assert.equal(progress.all11,null);const ref=await exclusive(`${directory}/all11.json`,{version:1,kind:'rollout004-all11',sealedAt:new Date().toISOString(),authority:progress.authority,baseline:progress.baseline,policy:progress.policyRef,firstwave:progress.firstwave,continuation:progress.continuation,targets:progress.targets});progress.all11=ref;progress.artifacts.push(ref);await save(progress);return ref;}
export async function finalize(isolated){const {progress}=await loadBaseline();assert(progress.all11);assert.equal(progress.pending,null);const completion=JSON.parse(await authenticate(isolated));assert.equal(completion.status,'passed');progress.isolated=isolated;const report={...progress,status:'passed',sealedAt:new Date().toISOString()};await verifyProductionReport(report,{authenticate,json:async ref=>JSON.parse(await authenticate(ref)),currentAuthority,preservation:async ref=>JSON.parse(await authenticate(ref)),assertPreserved});return exclusive(reportPath,report);}
async function main(){const [command,value,expectedProgress,expectedBridge]=process.argv.slice(2);const actions={prepare,enable,apply:()=>apply(Number(value)),audit:()=>audit(value?value.split(',').map(Number):undefined),'recover-audit':()=>recoverAudit(Number(value),expectedProgress,expectedBridge),'recover-policy-only':()=>recoverPolicyOnly(Number(value),expectedProgress,expectedBridge),'recover-observed-completed':()=>recoverObservedCompleted(Number(value),expectedProgress,expectedBridge),'seal-firstwave':sealFirstwave,'seal-all11':sealAll11,continuation:async()=>recordContinuation(await json(value)),finalize:async()=>finalize(await reference(value))};assert(actions[command],'Explicit rollout command required');const result=await actions[command]();console.log(JSON.stringify({command,result}));}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(error=>{console.error(safeFailure(error).message);process.exitCode=1;});
